const body = $json.body ?? $json;

if (body.event && !['messages.upsert', 'MESSAGES_UPSERT'].includes(body.event)) {
  return [];
}

const payload = body.data ?? body;
const key = payload.key ?? {};

if (key.fromMe === true) {
  return [];
}

const remoteJid = key.remoteJid ?? body.sender ?? '';
if (!remoteJid || remoteJid.endsWith('@g.us')) {
  return [];
}

let text =
  payload.message?.conversation ??
  payload.message?.extendedTextMessage?.text ??
  payload.message?.imageMessage?.caption ??
  payload.message?.videoMessage?.caption ??
  payload.message?.documentMessage?.caption ??
  payload.message?.buttonsResponseMessage?.selectedDisplayText ??
  payload.message?.listResponseMessage?.title ??
  payload.message?.listResponseMessage?.singleSelectReply?.selectedRowId ??
  '';

text = String(text || '').trim();
if (!text) {
  return [];
}

const number = remoteJid
  .replace(/@s\.whatsapp\.net|@g\.us/g, '')
  .replace(/\D/g, '');

if (!number) {
  return [];
}

return [{
  json: {
    instance: body.instance ?? body.instanceName ?? '',
    remoteJid,
    number,
    pushName: payload.pushName ?? body.pushName ?? 'Cliente',
    inboundText: text
  }
}];

const input = $json;

// Versao sem acesso a env vars (compatível com n8n bloqueando $env no Code node)
const cfg = {
  maxInputChars: 500,
  maxOutputChars: 280,
  maxOutputTokens: 120,
  maxMsgsPerHour: 25,
  maxMsgsPerDay: 200,
  workTimezone: 'America/Bahia',
  workDays: [1, 2, 3, 4, 5],
  workWindows: ['08:00-12:00', '13:30-18:00'],
  outOfHoursMessage: 'Atendimento automatico ativo de segunda a sexta, das 08:00 as 12:00 e das 13:30 as 18:00.',
  highVolumeMessage: 'Estou com alto volume no momento. Tente novamente em alguns minutos.'
};

const now = new Date();
const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: cfg.workTimezone,
  weekday: 'short',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false
}).formatToParts(now);

const p = Object.fromEntries(parts.map((x) => [x.type, x.value]));
const weekdayMap = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
const dow = weekdayMap[p.weekday] || 0;
const hh = Number(p.hour || '0');
const mm = Number(p.minute || '0');
const minutesNow = (hh * 60) + mm;
const dayKey = `${p.year}-${p.month}-${p.day}`;
const hourKey = `${dayKey}-${String(hh).padStart(2, '0')}`;

function hhmmToMinutes(hhmm) {
  const [h, m] = String(hhmm).split(':').map((v) => Number(v));
  return (h * 60) + m;
}

function inAnyWindow(value, windows) {
  for (const w of windows) {
    const [start, end] = w.split('-').map((v) => v.trim());
    if (!start || !end) continue;
    const s = hhmmToMinutes(start);
    const e = hhmmToMinutes(end);
    if (value >= s && value < e) return true;
  }
  return false;
}

const inWorkDay = cfg.workDays.includes(dow);
const inWorkTime = inAnyWindow(minutesNow, cfg.workWindows);
const inBusinessHours = inWorkDay && inWorkTime;

const staticData = $getWorkflowStaticData('global');
if (!staticData.dailyCounts) staticData.dailyCounts = {};
if (!staticData.hourlyCounts) staticData.hourlyCounts = {};

for (const key of Object.keys(staticData.dailyCounts)) {
  if (key !== dayKey) delete staticData.dailyCounts[key];
}
for (const key of Object.keys(staticData.hourlyCounts)) {
  if (!key.startsWith(dayKey)) delete staticData.hourlyCounts[key];
}

let allowAi = true;
let blockReason = '';

if (!inBusinessHours) {
  allowAi = false;
  blockReason = 'out_of_hours';
} else {
  const nextDaily = Number(staticData.dailyCounts[dayKey] || 0) + 1;
  const nextHourly = Number(staticData.hourlyCounts[hourKey] || 0) + 1;

  if (nextDaily > cfg.maxMsgsPerDay || nextHourly > cfg.maxMsgsPerHour) {
    allowAi = false;
    blockReason = 'volume';
  } else {
    staticData.dailyCounts[dayKey] = nextDaily;
    staticData.hourlyCounts[hourKey] = nextHourly;
  }
}

const inboundText = String(input.inboundText || '').slice(0, cfg.maxInputChars).trim();

const fallbackText = blockReason === 'volume'
  ? cfg.highVolumeMessage
  : cfg.outOfHoursMessage;

return [{
  json: {
    instance: input.instance || '',
    number: input.number,
    pushName: input.pushName,
    inboundTextOriginal: input.inboundText,
    promptInput: inboundText,
    allowAi,
    blockReason,
    maxOutputChars: cfg.maxOutputChars,
    maxOutputTokens: cfg.maxOutputTokens,
    fallbackText
  }
}];

