const response = $json;
const guardrails = $node['Guardrails'].json;

let reply = response.output_text ?? '';

if (!reply && Array.isArray(response.output)) {
  reply = response.output
    .flatMap((item) => item?.content ?? [])
    .map((part) => part?.text ?? '')
    .filter(Boolean)
    .join('\n')
    .trim();
}

if (!reply) {
  reply = 'Desculpe, nao consegui responder agora. Pode repetir sua mensagem?';
}

reply = String(reply).slice(0, Number(guardrails.maxOutputChars || 280));

return [{
  json: {
    instance: guardrails.instance || '',
    number: guardrails.number,
    replyText: reply
  }
}];

const payload = $json;
const maxOutputChars = Number(payload.maxOutputChars || 280);
const text = String(payload.fallbackText || 'Atendimento indisponivel no momento.').slice(0, maxOutputChars);

return [{
  json: {
    instance: payload.instance || '',
    number: payload.number,
    replyText: text
  }
}];
